// @param hidden enum _MaskSource = Constant1 {Constant1: 0, MapChannel: 1, InputAlpha: 2, SeparateTexture: 3} // Constant1 needs no second texture; MapChannel reuses the displacement map.
// @if _MaskSource != 0
// @param bool _InvertMask = false
// @param curve _MaskProfile // Remaps mask values; the default linear curve preserves them.
// @endif
// @if _MaskSource == 1
// @param enum _MapMaskChannel = Alpha {Alpha: 0, Luminance: 1, R: 2, G: 3, B: 4}
// @endif
// @if _MaskSource == 3
// @param texture2D _StrengthMask = none // Optional second texture. Leave Mask Source at Constant1 to work with only one map.
// @param enum _SeparateMaskChannel = Alpha {Alpha: 0, Luminance: 1, R: 2, G: 3, B: 4}
// @endif
// @endgroup
// @group(Output Mix; _Mix)
// @param hidden float _Mix = 1 [0 .. 1] // Blend the displaced sample with the original image.
// @param enum _InputEdge = Clamp {Clamp: 0, Repeat: 1, Mirror: 2, Transparent: 3} // Addressing for displaced image samples, independent of map wrapping.
// @endgroup

float ReadDisplacementChannel(float4 value, float channel)
{
    float result = dot(value.rgb, float3(0.2126, 0.7152, 0.0722));
    if (channel > 0.5 && channel < 1.5) result = value.r;
    else if (channel > 1.5 && channel < 2.5) result = value.g;
    else if (channel > 2.5 && channel < 3.5) result = value.b;
    else if (channel > 3.5) result = value.a;
    return result;
}

float ReadStrengthChannel(float4 value, float channel)
{
    float result = value.a;
    if (channel > 0.5 && channel < 1.5) result = dot(value.rgb, float3(0.2126, 0.7152, 0.0722));
    else if (channel > 1.5 && channel < 2.5) result = value.r;
    else if (channel > 2.5 && channel < 3.5) result = value.g;
    else if (channel > 3.5) result = value.b;
    return result;
}

float2 AddressMapUV(float2 uv, float mode, float2 texelSize)
{
    if (mode < 0.5)
        return clamp(uv, texelSize * 0.5, 1.0 - texelSize * 0.5);
    if (mode < 1.5)
        uv = frac(uv);
    else
        uv = 1.0 - abs(frac(uv * 0.5) * 2.0 - 1.0);
    return uv;
}

float2 AddressInputUV(float2 uv, float mode, float2 texelSize, out float inside)
{
    inside = 1.0;
    if (mode < 0.5)
        return clamp(uv, texelSize * 0.5, 1.0 - texelSize * 0.5);
    if (mode < 1.5)
        return frac(uv);
    if (mode < 2.5)
        return 1.0 - abs(frac(uv * 0.5) * 2.0 - 1.0);

    inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
    return clamp(uv, texelSize * 0.5, 1.0 - texelSize * 0.5);
}

float ReadHeightAtUV(float2 uv, float2 mapDDX, float2 mapDDY)
{
    float2 mapUV = AddressMapUV(_MapTransform_ToLocal(uv), _MapWrap, _DisplacementMap_TexelSize.xy);
    float height = saturate(ReadDisplacementChannel(tex2Dgrad(_DisplacementMap, mapUV, mapDDX, mapDDY), _MapChannel));
    return _InvertHeight > 0.5 ? 1.0 - height : height;
}

float2 DirectionFromAngle(float angle)
{
    float sine, cosine;
    sincos(radians(angle), sine, cosine);
    return float2(cosine, sine);
}

float2 TraceParallax(float2 uv, float strengthMask, float2 mapDDX, float2 mapDDY, out float hitHeight)
{
    int steps = clamp((int)round(_ParallaxSteps), 4, 32);
    float elevation = radians(clamp(_ViewElevation, 5.0, 85.0));
    float lateralPixels = _Depth * strengthMask / max(tan(elevation), 1e-3);
    float2 stepUV = DirectionFromAngle(_ViewAngle) * lateralPixels * _CanvasSize.zw / steps;
    float layerStep = 1.0 / steps;
    float rayDepth = 0.0;
    float2 previousUV = uv;
    float2 currentUV = uv;
    hitHeight = 0.0;

    [loop]
    for (int i = 0; i < 32; i++)
    {
        if (i >= steps) break;
        previousUV = currentUV;
        currentUV -= stepUV;
        rayDepth += layerStep;
        hitHeight = ReadHeightAtUV(currentUV, mapDDX, mapDDY);
        float surfaceDepth = 1.0 - hitHeight;
        if (rayDepth >= surfaceDepth)
        {
            float previousDepth = rayDepth - layerStep;
            float beforeHit = surfaceDepth - previousDepth;
            float afterHit = rayDepth - surfaceDepth;
            float blend = saturate(beforeHit / max(beforeHit + afterHit, 1e-6));
            currentUV = lerp(previousUV, currentUV, blend);
            hitHeight = ReadHeightAtUV(currentUV, mapDDX, mapDDY);
            break;
        }
    }
    return currentUV;
}

