float2 GrayscaleDirection(float2 uv)
{
    float2 direction = float2(1.0, 0.0);
    if (_Direction > 0.5 && _Direction < 1.5)
        direction = float2(0.0, 1.0);
    else if (_Direction > 1.5 && _Direction < 3.5)
    {
        float2 radial = (uv - _Center) * _CanvasSize.xy;
        float radius = length(radial);
        direction = radius > 1e-6 ? radial / radius : float2(0.0, 0.0);
        if (_Direction > 2.5)
            direction = float2(-direction.y, direction.x);
    }
    else if (_Direction > 3.5)
    {
        float sine, cosine;
        sincos(radians(_Angle), sine, cosine);
        direction = float2(cosine, sine);
    }
    return direction;
}

float4 ApplyFX(float2 uv, float4 color)
{
    float2 mapUV = _MapTransform_ToLocal(uv);
    float2 mapDDX = ddx(mapUV);
    float2 mapDDY = ddy(mapUV);
    mapUV = AddressMapUV(mapUV, _MapWrap, _DisplacementMap_TexelSize.xy);
    float4 mapSample = tex2D(_DisplacementMap, mapUV);
    float2 displacementPixels = float2(0.0, 0.0);
    float2 parallaxUV = uv;
    float parallaxHeight = 0.0;

    if (_Mode < 0.5)
    {
        displacementPixels = (mapSample.rg - float2(_Neutral, _Neutral)) * 2.0 * float2(_StrengthX, _StrengthY);
    }
    else if (_Mode < 1.5)
    {
        float mapValue = ReadDisplacementChannel(mapSample, _MapChannel);
        float signedValue = (mapValue - _Neutral) * 2.0;
        displacementPixels = GrayscaleDirection(uv) * signedValue * _Strength;
    }

    float strengthMask = 1.0;
    if (_MaskSource > 0.5)
    {
        float maskValue = 1.0;
        if (_MaskSource < 1.5)
            maskValue = ReadStrengthChannel(mapSample, _MapMaskChannel);
        else if (_MaskSource < 2.5)
            maskValue = color.a;
        else
        {
            float2 strengthMaskUV = AddressMapUV(_MapTransform_ToLocal(uv), _MapWrap, _StrengthMask_TexelSize.xy);
            maskValue = ReadStrengthChannel(tex2D(_StrengthMask, strengthMaskUV), _SeparateMaskChannel);
        }
        maskValue = lerp(maskValue, 1.0 - maskValue, step(0.5001, _InvertMask));
        strengthMask = saturate(_MaskProfile_Sample(saturate(maskValue)));
    }

    if (_Mode > 1.5)
        parallaxUV = TraceParallax(uv, strengthMask, mapDDX, mapDDY, parallaxHeight);

    float2 inputUV = _Mode > 1.5 ? parallaxUV : uv + displacementPixels * strengthMask * _CanvasSize.zw;
    float inside;
    inputUV = AddressInputUV(inputUV, _InputEdge, _MainTex_TexelSize.xy, inside);
    float4 distorted = SampleInput(inputUV) * inside;
    // if (_Mode > 1.5 && _SelfShadow > 0.5)
    // {
    //     float visibility = TraceParallaxSelfShadow(parallaxUV, parallaxHeight, strengthMask, mapDDX, mapDDY);
    //     distorted.rgb *= lerp(1.0, visibility, saturate(_ShadowStrength));
    // }
    float4 result = lerp(color, distorted, saturate(_Mix));
    return result;
}

// @whimtex-effect Color/Levels
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1] // Blend between the original and corrected colors.
// @group
// @header(Input Levels)
// @param label(Input Black) float _InBlack = 0 [0 .. ~1] // Input black point. At or above white, the mapping becomes a hard threshold.
// @param label(Input White) float _InWhite = 1 [0 .. ~1] // Input white point.
// @param float _Gamma = 1 [0.1 .. ~5] // Midtone brightness.
// @param curve _Curve // Remap tones after input levels and Gamma, before output levels. Linear leaves the mapping unchanged.
// @header(Output Levels)
// @param label(Output Black) float _OutBlack = 0 [0 .. ~1] // Output black point, including originally black pixels.
// @param label(Output White) float _OutWhite = 1 [0 .. ~1] // Output white point; values below black invert the output.
// @param bool _PreserveColor = true // On adjusts luminance; off applies levels independently to RGB.
// @endgroup

float MapLevels(float value)
{
    float mapped;
    if (_InWhite <= _InBlack) mapped = step(_InBlack, value);
    else mapped = saturate((value - _InBlack) / (_InWhite - _InBlack));
    mapped = pow(mapped, 1.0 / max(_Gamma, 0.0001));
    mapped = _Curve_Sample(mapped);
    return lerp(_OutBlack, _OutWhite, mapped);
}

float4 ApplyFX(float2 uv, float4 color)
{
	float4 result = color;
    float3 rgb = max(color.rgb, 0.0);
    if (_PreserveColor > 0.5)
    {
        float luma = dot(rgb, float3(0.2126, 0.7152, 0.0722));
        float mapped = MapLevels(luma);
		result.rgb = luma > 0.000001 ? rgb * (mapped / max(luma, 0.000001)) : mapped.xxx;
	}
	else
	{
		result.rgb = float3(MapLevels(rgb.r), MapLevels(rgb.g), MapLevels(rgb.b));
	}
	return lerp(color, result, _Opacity);
}

